#include <iostream>
#include <string>
#include <vector>
using namespace std;

class Cat {
protected:
    string name;
    int age;
public:
    Cat(string n, int a) : name(n), age(a) {}
    void greet() {
        cout << "我是" << name << "，今年 " << age << " 岁喵" << endl;
    }
};

class Kitten : public Cat {
protected:
    int days;
public:
    Kitten(string n, int a, int d) : Cat(n, a), days(d) {}
    void showDays() {
        cout << name << " 出生 " << days << " 天啦" << endl;
    }
};

int main() {
    vector<Cat> roster;
    roster.push_back(Cat("小橘", 3));
    roster.push_back(Cat("大胖", 5));
    cout << roster.size() << endl;
    for (Cat& c : roster) {
        c.greet();
    }

    Kitten k("棉花", 1, 20);
    k.greet();
    k.showDays();
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
using namespace std;

class Cat {
protected:
    string name;
    int age;
public:
    Cat(string n, int a) : name(n), age(a) {}
    void greet() {
        cout << "我是" << name << "，今年 " << age << " 岁喵" << endl;
    }
};

int main() {
    vector<Cat> roster;
    vector<int> keys = {1, 1, 0, 1};

    for (int cmd : keys) {
        if (cmd == 0) {
            cout << "收摊喵，今天登记了 " << roster.size() << " 只" << endl;
            break;
        } else if (cmd == 1) {
            roster.push_back(Cat("小橘", 3));
        } else {
            cout << "本喵还不会这个号码喵" << endl;
        }
    }
    cout << "走出去之后名册上 " << roster.size() << " 只" << endl;
    return 0;
}
